def numoffbt(arr, n):
    MOD = 1000000007
    max_val = max(arr)
    dp = [0] * (max_val + 1)
    count = [0] * (max_val + 1)

    for x in arr:
        count[x] += 1

    for i in range(2, max_val + 1):
        if count[i]:
            for j in range(2, int(i**0.5) + 1):
                if i % j == 0:
                    k = i // j
                    if k <= max_val:
                        if j != k:
                            dp[i] = (dp[i] + dp[j] * dp[k] * count[j] * count[k]) % MOD
                        else:
                            dp[i] = (dp[i] + dp[j] * (dp[j] - 1) // 2 * count[j] * count[j]) % MOD
            dp[i] = (dp[i] + count[i]) % MOD

    return sum(dp) % MOD
